def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            result.append((color, cells))
    return result


def _is_l(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    h = max(r for r, c in cells) - r0 + 1
    w = max(c for r, c in cells) - c0 + 1
    if h < 3 or w < 3:
        return False
    shape = {(r - r0, c - c0) for r, c in cells}
    return any(
        shape == ({(rr, c) for c in range(w)} | {(r, cc) for r in range(h)})
        for rr in (0, h - 1)
        for cc in (0, w - 1)
    )


def _normalized(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r - r0, c - c0) for r, c in cells)


def transform(grid):
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    objects = _components(grid)
    markers = [(color, cells) for color, cells in objects if color != background and _is_l(cells)]
    if not markers:
        return [row[:] for row in grid]
    marker_color, marker = max(markers, key=lambda item: len(item[1]))

    groups = defaultdict(list)
    for color, cells in objects:
        if color != background and cells != marker:
            groups[_normalized(cells)].append((color, cells))
    repeated = [(shape, items) for shape, items in groups.items() if len(items) > 1]
    if not repeated:
        return [row[:] for row in grid]

    r0 = min(r for r, c in marker)
    c0 = min(c for r, c in marker)
    marker_h = max(r for r, c in marker) - r0 + 1
    marker_w = max(c for r, c in marker) - c0 + 1
    marker_aspect = max(marker_h, marker_w) / min(marker_h, marker_w)

    # An elongated L marker indicates which orientation of repeated shape to use.
    if marker_aspect >= 1.5:
        horizontal = marker_w > marker_h
        oriented = []
        for shape, items in repeated:
            sh = max(r for r, c in shape) + 1
            sw = max(c for r, c in shape) + 1
            if (sw > sh) == horizontal and sw != sh:
                oriented.append((shape, items))
        if oriented:
            repeated = oriented

    largest = max(len(shape) for shape, _ in repeated)
    candidates = [(shape, items) for shape, items in repeated if len(shape) == largest]

    def aspect_difference(shape):
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        aspect = max(sh, sw) / min(sh, sw)
        return abs(aspect - marker_aspect)

    shape, items = min(candidates, key=lambda pair: aspect_difference(pair[0]))

    def distance(cells):
        return min(abs(r - mr) + abs(c - mc) for r, c in cells for mr, mc in marker)

    _, target = max(items, key=lambda item: distance(item[1]))
    output = [row[:] for row in grid]
    for r, c in target:
        output[r][c] = marker_color
    return output
